const lit=p=>(x,y,r)=>{if(night()>.2)glowAt(p,x,y,r,'255,228,160',.35*night())};
const blink=(i,f=4)=>!mv()||((ph()*f+i)|0)%2===0;

/* ===================== FLOOR (store corners, beside the counter, shop corner) ===================== */
