function bulbs(cols,mode,o){let i=0;const pts=[];for(let x=6;x<(S.sv.open?330:200);x+=12)pts.push([x,0]);for(let y=6;y<150;y+=12)pts.push([0,y]);const s=DV.s,cxx=DV.cx;
  if(mode==='led'){for(const seg of [[[0,0,76],[S.sv.open?330:200,0,76]],[[0,0,76],[0,150,76]]]){const [a,b]=P(...seg[0]),[c2,d2]=P(...seg[1]);cxx.save();cxx.shadowColor=cols[0];cxx.shadowBlur=6+night()*10;cxx.strokeStyle=cols[0];cxx.lineWidth=Math.max(1.4,1.2*s);cxx.beginPath();cxx.moveTo(a,b);cxx.lineTo(c2,d2);cxx.stroke();cxx.restore()}return}
  for(const [x,y] of pts){const z=74+Math.sin((x+y)*.2)*2,[a,b]=P(x,y,z),c=cols[i%cols.length],on=mode==='twinkle'?((ph()*2+i)|0)%4!==0||!mv():mode==='chase'?((ph()*6-i)|0)%3===0||!mv():true;i++;
    if(on&&night()>.2)glow(a,b,7,'255,240,200',.25+.3*night());cxx.fillStyle=on?c:'#555';
    if(mode==='globe'){cxx.beginPath();cxx.arc(a,b+1.2*s,Math.max(2,1.8*s*1.6),0,7);cxx.fill()}else if(mode==='icicle'){cxx.beginPath();cxx.moveTo(a-1.4*s,b);cxx.lineTo(a+1.4*s,b);cxx.lineTo(a,b+(5+(i%3)*2)*s);cxx.fill()}
    else if(mode==='lantern'){cxx.beginPath();cxx.ellipse(a,b+2*s,1.6*s*1.6,2.2*s*1.6,0,0,7);cxx.fill()}else if(mode==='star'){const q=spr(a,b+2*s,s);q.star(0,0,2.4,on?c:'#555')}else{cxx.beginPath();cxx.arc(a,b,Math.max(1.4,1.1*s*1.6),0,7);cxx.fill()}}}
